    'planner.saveExamDate': { en: 'Save exam date', hi: 'परीक्षा तिथि सहेजें', ta: 'தேர்வு தேதியைச் சேமிக்கவும்', bn: 'পরীক্ষার তারিখ সংরক্ষণ করুন', te: 'పరీక్ష తేదీని సేవ్ చేయండి', mr: 'परीक्षा तारीख जतन करा' },
    'planner.syllabusClear': { en: 'Your syllabus is clear for now.', hi: 'अभी आपका सिलेबस व्यवस्थित है।', ta: 'இப்போது உங்கள் பாடத்திட்டம் தெளிவாக உள்ளது.', bn: 'এই মুহূর্তে আপনার সিলেবাস পরিষ্কার।', te: 'ప్రస్తుతం మీ సిలబస్ స్పష్టంగా ఉంది.', mr: 'आत्ता तुमचा अभ्यासक्रम व्यवस्थित आहे.' },
