    'quiz.submit': { en: 'Submit quiz', hi: 'क्विज़ जमा करें', ta: 'வினாடி வினாவைச் சமர்ப்பி', bn: 'কুইজ জমা দিন', te: 'క్విజ్ సమర్పించండి', mr: 'क्विझ सबमिट करा' },
