    'quiz.unansweredWarning': { en: '{count} questions are unanswered. Submit anyway?', hi: '{count} प्रश्नों के उत्तर नहीं दिए गए। फिर भी जमा करें?', ta: '{count} வினாக்களுக்கு பதில் அளிக்கவில்லை. இருந்தாலும் சமர்ப்பிக்கவா?', bn: '{count}টি প্রশ্নের উত্তর দেওয়া হয়নি। তবুও জমা দেবেন?', te: '{count} ప్రశ్నలకు సమాధానం ఇవ్వలేదు. అయినా సమర్పించాలా?', mr: '{count} प्रश्नांची उत्तरे दिलेली नाहीत. तरीही सबमिट करायचे?' },
