    'quiz.resultTitle': { en: "Today's result", hi: 'आज का परिणाम', ta: 'இன்றைய முடிவு', bn: 'আজকের ফলাফল', te: 'ఈరోజు ఫలితం', mr: 'आजचा निकाल' },
    'quiz.score': { en: '{correct} / {total} correct', hi: '{correct} / {total} सही', ta: '{correct} / {total} சரி', bn: '{correct} / {total} সঠিক', te: '{correct} / {total} సరైనవి', mr: '{correct} / {total} बरोबर' },
    'quiz.missedToRevision': { en: 'Questions you missed were added to your revision cards for tomorrow.', hi: 'जो प्रश्न छूट गए, वे कल के लिए आपके revision cards में जोड़ दिए गए हैं।', ta: 'நீங்கள் தவறவிட்ட வினாக்கள் நாளைக்கான மீள்பார்வை அட்டைகளில் சேர்க்கப்பட்டன.', bn: 'যে প্রশ্নগুলো ভুল হয়েছে, সেগুলো আগামীকালের রিভিশন কার্ডে যোগ করা হয়েছে।', te: 'మీరు తప్పిన ప్రశ్నలు రేపటి రివిజన్ కార్డులలో చేర్చబడ్డాయి.', mr: 'चुकलेले प्रश्न उद्याच्या रिव्हिजन कार्डमध्ये जोडले आहेत.' },
    'quiz.correct': { en: 'Correct', hi: 'सही', ta: 'சரி', bn: 'সঠিক', te: 'సరైనది', mr: 'बरोबर' },
    'quiz.incorrect': { en: 'Incorrect', hi: 'गलत', ta: 'தவறு', bn: 'ভুল', te: 'తప్పు', mr: 'चूक' },
