    'quiz.streak': { en: '{count}-day streak', hi: '{count} दिन की streak', ta: '{count} நாள் தொடர்', bn: '{count} দিনের স্ট্রিক', te: '{count} రోజుల స్ట్రీక్', mr: '{count} दिवसांची स्ट्रीक' },
    'quiz.streakStart': { en: 'Start your streak today', hi: 'आज से अपनी streak शुरू करें', ta: 'இன்றே உங்கள் தொடரைத் தொடங்குங்கள்', bn: 'আজই আপনার স্ট্রিক শুরু করুন', te: 'ఈరోజే మీ స్ట్రీక్ ప్రారంభించండి', mr: 'आजच तुमची स्ट्रीक सुरू करा' },
    'quiz.unavailableTitle': { en: 'Daily quiz is coming soon', hi: 'डेली क्विज़ जल्द आ रहा है', ta: 'தினசரி வினாடி வினா விரைவில் வருகிறது', bn: 'দৈনিক কুইজ শীঘ্রই আসছে', te: 'రోజువారీ క్విజ్ త్వరలో వస్తోంది', mr: 'दैनिक क्विझ लवकरच येत आहे' },
    'quiz.unavailableText': { en: 'Verified previous-year questions for your exam are being added. Check back soon.', hi: 'आपकी परीक्षा के सत्यापित पिछले वर्षों के प्रश्न जोड़े जा रहे हैं। जल्द फिर देखें।', ta: 'உங்கள் தேர்வுக்கான சரிபார்க்கப்பட்ட முந்தைய ஆண்டு வினாக்கள் சேர்க்கப்படுகின்றன. விரைவில் மீண்டும் பாருங்கள்.', bn: 'আপনার পরীক্ষার যাচাই করা বিগত বছরের প্রশ্ন যোগ করা হচ্ছে। শীঘ্রই আবার দেখুন।', te: 'మీ పరీక్షకు ధృవీకరించిన గత సంవత్సరం ప్రశ్నలు జోడించబడుతున్నాయి. త్వరలో మళ్ళీ చూడండి.', mr: 'तुमच्या परीक्षेचे पडताळलेले मागील वर्षांचे प्रश्न जोडले जात आहेत. लवकरच पुन्हा पाहा.' },
    'quiz.comeBackTomorrow': { en: 'A new quiz unlocks tomorrow.', hi: 'नया क्विज़ कल खुलेगा।', ta: 'புதிய வினாடி வினா நாளை திறக்கும்.', bn: 'নতুন কুইজ আগামীকাল খুলবে।', te: 'కొత్త క్విజ్ రేపు అందుబాటులోకి వస్తుంది.', mr: 'नवीन क्विझ उद्या उघडेल.' },
    'quiz.loadError': { en: "Could not load today's quiz.", hi: 'आज का क्विज़ लोड नहीं हो सका।', ta: 'இன்றைய வினாடி வினாவை ஏற்ற முடியவில்லை.', bn: 'আজকের কুইজ লোড করা যায়নি।', te: 'ఈరోజు క్విజ్ లోడ్ కాలేదు.', mr: 'आजचा क्विझ लोड झाला नाही.' },
    'quiz.submitError': { en: 'Could not submit the quiz. Your answers are still here; try again.', hi: 'क्विज़ जमा नहीं हो सका। आपके उत्तर सुरक्षित हैं; फिर प्रयास करें।', ta: 'வினாடி வினாவைச் சமர்ப்பிக்க முடியவில்லை. உங்கள் பதில்கள் இங்கேயே உள்ளன; மீண்டும் முயற்சிக்கவும்.', bn: 'কুইজ জমা দেওয়া যায়নি। আপনার উত্তর রয়ে গেছে; আবার চেষ্টা করুন।', te: 'క్విజ్ సమర్పించలేకపోయాం. మీ సమాధానాలు ఇక్కడే ఉన్నాయి; మళ్ళీ ప్రయత్నించండి.', mr: 'क्विझ सबमिट झाला नाही. तुमची उत्तरे इथेच आहेत; पुन्हा प्रयत्न करा.' },
