    'offline.savedHeading': { en: 'Saved on this device', hi: 'इस डिवाइस पर सहेजा गया', ta: 'இந்தச் சாதனத்தில் சேமிக்கப்பட்டது', bn: 'এই ডিভাইসে সেভ করা', te: 'ఈ పరికరంలో సేవ్ చేసినవి', mr: 'या डिव्हाइसवर जतन केलेले' },
    'offline.downloadHint': { en: 'Download your workspace before travelling or losing connectivity.', hi: 'यात्रा से पहले या इंटरनेट जाने से पहले अपना वर्कस्पेस डाउनलोड करें।', ta: 'பயணத்திற்கு முன் அல்லது இணைப்பு இழக்கும் முன் பணியிடத்தைப் பதிவிறக்கவும்.', bn: 'ভ্রমণ বা সংযোগ হারানোর আগে ওয়ার্কস্পেস ডাউনলোড করুন।', te: 'ప్రయాణానికి ముందు లేదా కనెక్షన్ పోయే ముందు వర్క్‌స్పేస్ డౌన్‌లోడ్ చేయండి.', mr: 'प्रवासापूर्वी किंवा इंटरनेट जाण्यापूर्वी तुमचे कार्यक्षेत्र डाउनलोड करा.' },
    'offline.preparing': { en: 'Preparing workspace…', hi: 'वर्कस्पेस तैयार हो रहा है…', ta: 'பணியிடம் தயாராகிறது…', bn: 'ওয়ার্কস্পেস প্রস্তুত হচ্ছে…', te: 'వర్క్‌స్పేస్ సిద్ధమవుతోంది…', mr: 'कार्यक्षेत्र तयार होत आहे…' },
    'offline.downloadMedia': { en: 'Download selected media', hi: 'चुनी गई मीडिया डाउनलोड करें', ta: 'தேர்ந்தெடுத்த மீடியாவைப் பதிவிறக்கு', bn: 'নির্বাচিত মিডিয়া ডাউনলোড করুন', te: 'ఎంచుకున్న మీడియా డౌన్‌లోడ్ చేయండి', mr: 'निवडलेली मीडिया डाउनलोड करा' },
    'offline.preparingMetadata': { en: 'Preparing metadata', hi: 'जानकारी तैयार हो रही है', ta: 'விவரங்கள் தயாராகின்றன', bn: 'তথ্য প্রস্তুত হচ্ছে', te: 'వివరాలు సిద్ధమవుతున్నాయి', mr: 'माहिती तयार होत आहे' },
    'offline.downloadingMedia': { en: 'Downloading media', hi: 'मीडिया डाउनलोड हो रहा है', ta: 'மீடியா பதிவிறங்குகிறது', bn: 'মিডিয়া ডাউনলোড হচ্ছে', te: 'మీడియా డౌన్‌లోడ్ అవుతోంది', mr: 'मीडिया डाउनलोड होत आहे' },
    'offline.syncNote': { en: 'Timetable, resources, annotations and study activity sync idempotently.', hi: 'समय-सारणी, संसाधन, टिप्पणियां और अध्ययन गतिविधि सुरक्षित रूप से सिंक होती हैं।', ta: 'கால அட்டவணை, வளங்கள், குறிப்புகள் மற்றும் படிப்புச் செயல்பாடுகள் பாதுகாப்பாக ஒத்திசைக்கப்படும்.', bn: 'রুটিন, রিসোর্স, টীকা ও পড়াশোনার কাজ নিরাপদে সিঙ্ক হয়।', te: 'టైమ్‌టేబుల్, వనరులు, వ్యాఖ్యలు మరియు అధ్యయన కార్యకలాపాలు సురక్షితంగా సింక్ అవుతాయి.', mr: 'वेळापत्रक, संसाधने, टिपा आणि अभ्यास कृती सुरक्षितपणे सिंक होतात.' },
    'offline.syncing': { en: 'Syncing…', hi: 'सिंक हो रहा है…', ta: 'ஒத்திசைக்கிறது…', bn: 'সিঙ্ক হচ্ছে…', te: 'సింక్ అవుతోంది…', mr: 'सिंक होत आहे…' },
    'offline.syncNow': { en: 'Sync now', hi: 'अभी सिंक करें', ta: 'இப்போது ஒத்திசை', bn: 'এখনই সিঙ্ক করুন', te: 'ఇప్పుడే సింక్ చేయండి', mr: 'आता सिंक करा' },
    'offline.conflictText': { en: 'This item changed on this phone and another device.', hi: 'यह आइटम इस फ़ोन और दूसरे डिवाइस दोनों पर बदला गया।', ta: 'இந்த உருப்படி இந்த ஃபோனிலும் வேறு சாதனத்திலும் மாற்றப்பட்டது.', bn: 'এই আইটেম এই ফোন ও অন্য ডিভাইস দুটোতেই বদলানো হয়েছে।', te: 'ఈ అంశం ఈ ఫోన్‌లో మరియు మరో పరికరంలో మారింది.', mr: 'हा घटक या फोनवर आणि दुसऱ्या डिव्हाइसवर बदलला.' },
    'offline.keepMine': { en: 'Keep mine', hi: 'मेरा रखें', ta: 'என்னுடையதை வை', bn: 'আমারটা রাখুন', te: 'నాదే ఉంచండి', mr: 'माझे ठेवा' },
    'offline.useLatest': { en: 'Use latest', hi: 'नवीनतम उपयोग करें', ta: 'சமீபத்தியதைப் பயன்படுத்து', bn: 'সর্বশেষটি ব্যবহার করুন', te: 'తాజాదాన్ని వాడండి', mr: 'नवीनतम वापरा' },
    'offline.noConflicts': { en: 'No unresolved conflicts', hi: 'कोई अनसुलझा टकराव नहीं', ta: 'தீர்க்கப்படாத முரண்பாடுகள் இல்லை', bn: 'কোনো অমীমাংসিত দ্বন্দ্ব নেই', te: 'పరిష్కరించని వైరుధ్యాలు లేవు', mr: 'कोणताही न सुटलेला संघर्ष नाही' },
    'offline.consistent': { en: 'Your cached workspace has a consistent version.', hi: 'आपके सहेजे वर्कस्पेस का संस्करण एक जैसा है।', ta: 'உங்கள் சேமித்த பணியிடம் ஒரே பதிப்பில் உள்ளது.', bn: 'আপনার সেভ করা ওয়ার্কস্পেসের সংস্করণ সামঞ্জস্যপূর্ণ।', te: 'మీ సేవ్ చేసిన వర్క్‌స్పేస్ వెర్షన్ ఒకేలా ఉంది.', mr: 'तुमच्या जतन केलेल्या कार्यक्षेत्राची आवृत्ती सुसंगत आहे.' },

