    'onboarding.studyTimeCaption': { en: 'Use realistic hours. Your timetable will adapt when real life changes.', hi: 'व्यावहारिक घंटे रखें। जीवन बदलने पर समय-सारणी भी बदलेगी।', ta: 'நடைமுறையான மணிநேரங்களைப் பயன்படுத்துங்கள். வாழ்க்கை மாறும்போது கால அட்டவணையும் மாறும்.', bn: 'বাস্তবসম্মত ঘণ্টা দিন। জীবন বদলালে রুটিনও মানিয়ে নেবে।', te: 'ఆచరణీయమైన గంటలు ఇవ్వండి. జీవితం మారినప్పుడు టైమ్‌టేబుల్ కూడా మారుతుంది.', mr: 'वास्तववादी तास द्या. आयुष्य बदलल्यावर वेळापत्रकही बदलेल.' },
    'onboarding.weekdayHours': { en: 'Weekdays (hours)', hi: 'सप्ताह के दिन (घंटे)', ta: 'வார நாட்கள் (மணி)', bn: 'সপ্তাহের দিন (ঘণ্টা)', te: 'వారపు రోజులు (గంటలు)', mr: 'आठवड्याचे दिवस (तास)' },
    'onboarding.weekendHours': { en: 'Weekends (hours)', hi: 'सप्ताहांत (घंटे)', ta: 'வார இறுதி (மணி)', bn: 'সাপ্তাহিক ছুটি (ঘণ্টা)', te: 'వారాంతాలు (గంటలు)', mr: 'आठवड्याच्या शेवटी (तास)' },
