    'briefing.aiPersonalised': { en: 'AI-PERSONALISED', hi: 'AI द्वारा व्यक्तिगत', ta: 'AI தனிப்பயனாக்கம்', bn: 'AI ব্যক্তিগতকৃত', te: 'AI వ్యక్తిగతీకరణ', mr: 'AI वैयक्तिकृत' },
    'briefing.ruleBased': { en: 'RULE-BASED • ALWAYS AVAILABLE', hi: 'नियम-आधारित • हमेशा उपलब्ध', ta: 'விதி அடிப்படை • எப்போதும் கிடைக்கும்', bn: 'নিয়মভিত্তিক • সবসময় উপলব্ধ', te: 'నియమ ఆధారిత • ఎల్లప్పుడూ అందుబాటులో', mr: 'नियमाधारित • नेहमी उपलब्ध' },
    'briefing.loadError': { en: 'Daily briefing could not load.', hi: 'दैनिक ब्रीफिंग लोड नहीं हो सकी।', ta: 'தினசரி சுருக்கத்தை ஏற்ற முடியவில்லை.', bn: 'দৈনিক ব্রিফিং লোড করা যায়নি।', te: 'రోజువారీ బ్రీఫింగ్ లోడ్ కాలేదు.', mr: 'दैनिक ब्रीफिंग लोड झाली नाही.' },
    'briefing.subtitle': { en: 'A focused summary built from your plan, performance and revision load.', hi: 'आपकी योजना, प्रदर्शन और रिवीजन भार से बना संक्षिप्त सारांश।', ta: 'உங்கள் திட்டம், செயல்திறன் மற்றும் மீள்பார்வைச் சுமையிலிருந்து உருவான சுருக்கம்.', bn: 'আপনার পরিকল্পনা, পারফরম্যান্স ও রিভিশনের চাপ থেকে তৈরি সারাংশ।', te: 'మీ ప్రణాళిక, పనితీరు మరియు రివిజన్ భారం నుండి రూపొందిన సారాంశం.', mr: 'तुमचे नियोजन, कामगिरी आणि उजळणी भार यांवरून तयार केलेला सारांश.' },
    'briefing.unavailable': { en: 'Briefing unavailable', hi: 'ब्रीफिंग उपलब्ध नहीं', ta: 'சுருக்கம் கிடைக்கவில்லை', bn: 'ব্রিফিং পাওয়া যাচ্ছে না', te: 'బ్రీఫింగ్ అందుబాటులో లేదు', mr: 'ब्रीफिंग उपलब्ध नाही' },
    'briefing.attention': { en: 'What deserves attention today', hi: 'आज किस पर ध्यान दें', ta: 'இன்று கவனிக்க வேண்டியது', bn: 'আজ কোন দিকে মনোযোগ দেবেন', te: 'ఈరోజు దేనిపై దృష్టి పెట్టాలి', mr: 'आज कशाकडे लक्ष द्यावे' },
    'briefing.noUrgent': { en: 'No urgent action. Follow today’s timetable and protect your revision blocks.', hi: 'कोई ज़रूरी काम नहीं। आज की समय-सारणी का पालन करें और रिवीजन सत्र बचाएं।', ta: 'அவசரச் செயல் இல்லை. இன்றைய கால அட்டவணையைப் பின்பற்றி மீள்பார்வை நேரங்களைக் காத்திடுங்கள்.', bn: 'জরুরি কিছু নেই। আজকের রুটিন মেনে চলুন এবং রিভিশনের সময় রক্ষা করুন।', te: 'అత్యవసర చర్య లేదు. ఈరోజు టైమ్‌టేబుల్ పాటించి రివిజన్ సమయాలను కాపాడండి.', mr: 'तातडीचे काही नाही. आजचे वेळापत्रक पाळा आणि उजळणी वेळा जपा.' },
    'briefing.currentAffairs': { en: 'Current-affairs links', hi: 'करंट अफेयर्स लिंक', ta: 'நடப்பு நிகழ்வு இணைப்புகள்', bn: 'কারেন্ট অ্যাফেয়ার্স লিঙ্ক', te: 'కరెంట్ అఫైర్స్ లింకులు', mr: 'चालू घडामोडी दुवे' },
